discrete EnergyCollectionSystem
port:
    event input real S1;  // Energy sources available
event input real S2;  // Collected or energy sources not available
state:
    initial state Idle
        when entry() then
            statehold(0);
        end;
        when receive(S1) then
            transition(Collecting);
        end;
    end;

    state Collecting
        when entry() then
            statehold(0);
        end;
        when receive(S2) then
            transition(Idle);
        end;
    end;
end;
end;

discrete EnergyStorageSystem
port:
    event input real C1;  // Storage command with energy available for storage
event input real C2;  // Energy storage devices are full or no additional energy is available for storage
event input real C3;  // Energy release
state:
    initial state Empty
        when entry() then
            statehold(0);
        end;
        when receive(C1) then
            transition(Storing);
        end;
    end;

    state Storing
        when entry() then
            statehold(0);
        end;
        when receive(C2) then
            transition(Full);
        end;
    end;

    state Full
        when entry() then
            statehold(0);
        end;
        when receive(C3) then
            transition(Empty);
        end;
    end;
end;
end;

discrete EnergyDistributionSystem
port:
    event input real D1;  // Allocation of requests
event input real D2;  // Distribution completed or request cancelled
state:
    initial state Standby
        when entry() then
            statehold(0);
        end;
        when receive(D1) then
            transition(Allocating);
        end;
    end;

    state Allocating
        when entry() then
            statehold(0);
        end;
        when receive(D2) then
            transition(Standby);
        end;
    end;
end;
end;

discrete EnergyOptimizationSystem
port:
    event input real O1;
    event input real O2;
state:
    initial state Normal
        when entry() then
            statehold(0);
        end;
        when receive(O1) then
            transition(Optimizing);
        end;
    end;

    state Optimizing
        when entry() then
            statehold(0);
        end;
        when receive(O2) then
            transition(Normal);
        end;
    end;
end;
end;

couple EnergyManagementSystem
import architectureModels.EnergyCollectionSystem as ECS;
import architectureModels.EnergyStorageSystem as ESS;
import architectureModels.EnergyDistributionSystem as EDS;
import architectureModels.EnergyOptimizationSystem as EOS;
part:
    ECS ecsInstance;
    ESS essInstance;
    EDS edsInstance;
    EOS eosInstance;
connection:
    connect(ecsInstance.EnergyOutput, essInstance.EnergyInput);
    connect(essInstance.StorageOutput, edsInstance.DistributionInput);
    connect(edsInstance.DistributionOutput, eosInstance.OptimizationInput);
    connect(eosInstance.OptimizationOutput, edsInstance.UpdateInput);
end;
